use verus::prelude::*;

// The function is pure, takes a slice of i32, and returns a boolean.
// Requires nothing (i.e. always callable).
// Ensures that `result` is true if and only if there
// exists an adjacent pair in `a` where the latter is exactly one
// greater than the former.
#[requires(true)]
#[ensures(
    result <==> 
    exists(|i: usize| i + 1 < a.len() && a[i] + 1 == a[i + 1])
)]
fn contains_consecutive_numbers(a: &[i32]) -> bool {
    a.windows(2).any(|w| w[0] + 1 == w[1])
}

